        c.burn(1);
        assert(c.totalSupply() == 500000000 * 1e18 - 1);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint256 amt, address recipient) public {
        require(amt > 0);

        // Acquire tokens via the airdrop so this contract can transfer them.
        c.getTokens();
        require(c.balanceOf(address(this)) >= amt);

        // Approve this contract (as spender) to spend exactly amt.
        c.approve(address(this), amt);
        require(c.allowance(address(this), address(this)) == amt);

        // Spend the entire allowance via transferFrom.
        bool ok = c.transferFrom(address(this), recipient, amt);
        require(ok);

        assert(c.allowance(address(this), address(this)) == 0);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function test(address _to, uint256 _w) public {
        require(_w > 0);
        // grant this contract an allowance of _w
        c.approve(address(this), _w);
        // spend 0 from this contract's balance (0 is always affordable)
        c.transferFrom(address(this), _to, 0);
        // allowance must be unchanged: _w - 0 == _w in P; M sets it to 0
        assert(c.allowance(address(this), address(this)) == _w);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(address to, uint256 amt) public {
        require(to != address(0));
        require(amt > 0 && amt <= 500e18);

        // acquire tokens so a transferFrom from this contract can succeed
        c.getTokens{value: 0}();

        // grant an allowance of exactly amt
        c.approve(address(this), amt);
        require(c.allowance(address(this), address(this)) == amt);

        // perform one transferFrom consuming the allowance
        c.transferFrom(address(this), to, amt);

        // on P the allowance is fully consumed (== 0);
        // on M it was incremented instead (== 2*amt)
        assert(c.allowance(address(this), address(this)) == 0);
    }

    receive() external payable {}
    fallback() external payable {}
}

